'use strict';
const {products,manufacturers}=window.HM_DATA;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}},write=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));return true}catch{toast('Your browser could not save this change.');return false}};
let saved=read('hm-v2-saved',[]).filter(id=>products.some(p=>p.id===id)),compared=[],category='All',limit=12;
const price=p=>p.price!==null?new Intl.NumberFormat('en-US',{style:'currency',currency:p.currency,maximumFractionDigits:Number.isInteger(p.price)?0:2}).format(p.price):'Price not published';
const priceHTML=p=>p.price!==null?`<small>${p.id==='m6'?'Early Access':'From'}</small> ${price(p)} <small>${p.currency}</small>`:p.status==='Research only'||p.status==='Development'||p.status==='Showcase'?'Research / showcase':p.status==='Waitlist'?'Join the waitlist':p.status==='Beta applications'?'Apply for beta':'Contact manufacturer';
const initials=p=>p.maker==='Boston Dynamics'?'BD':p.maker==='Apptronik'?'ap':p.maker==='NEURA Robotics'?'4NE1':p.maker==='Agility Robotics'?'Digit':p.maker==='Fourier'?'GR-3':p.maker==='AGIBOT'?'AGI':p.maker.split(' ').map(x=>x[0]).join('').slice(0,3);
const imageClass=p=>p.id==='m1'?'figure':p.id==='m6'?'neo':p.maker==='Unitree Robotics'&&p.image?'unitree':p.category!=='Robots'?'kit':'';
const art=p=>p.image?`<img src="${esc(p.image)}" alt="${esc(p.maker+' '+p.name+' — manufacturer product photo')}" loading="lazy">`:`<div class="mono-art"><strong>${esc(initials(p))}</strong><span>PLATFORM / ${esc(p.category.toUpperCase())}</span></div>`;
function filtered(){const q=$('#search').value.trim().toLowerCase();let list=products.filter(p=>(category==='All'||p.category===category)&&(!$('#makerFilter').value||p.maker===$('#makerFilter').value)&&(!$('#useFilter').value||p.use===$('#useFilter').value)&&(!$('#priced').checked||p.price!==null)&&(!$('#savedFilter').checked||saved.includes(p.id))&&`${p.name} ${p.maker} ${p.category} ${p.use}`.toLowerCase().includes(q));const sort=$('#sort').value;if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));if(sort==='low'||sort==='high')list.sort((a,b)=>a.price===null?b.price===null?0:1:b.price===null?-1:sort==='low'?a.price-b.price:b.price-a.price);return list}
function render(){const list=filtered();$('#results').textContent=`${list.length} ${list.length===1?'platform / offer':'platforms & offers'}${$('#savedFilter').checked?' · Saved':''}`;$('#savedCount').textContent=saved.length;$('#saved').style.color=$('#savedFilter').checked?'var(--lime)':'';$('#products').innerHTML=list.slice(0,limit).map(p=>`<article class="product"><div class="product-art ${imageClass(p)}"><button class="open-art" data-open="${p.id}" aria-label="Explore ${esc(p.name)}">${art(p)}</button><span class="status ${p.price!==null?'price-tag':''}">${esc(p.status.toUpperCase())}</span><button class="heart ${saved.includes(p.id)?'on':''}" data-save="${p.id}" aria-pressed="${saved.includes(p.id)}" aria-label="${saved.includes(p.id)?'Unsave':'Save'} ${esc(p.name)}">${saved.includes(p.id)?'♥':'♡'}</button></div><div class="product-info"><div class="maker-name">${esc(p.maker)} <span class="source-mark" title="Manufacturer source linked">↗</span></div><button class="product-title" data-open="${p.id}">${esc(p.name)}</button><div class="product-kind">${esc(p.category)} / ${esc(p.use)} / ${esc(p.form||'Humanoid platform')}</div><div class="product-price"><div>${priceHTML(p)}</div><button data-open="${p.id}" aria-label="View ${esc(p.name)} details">↗</button></div></div><label class="compare-check"><input type="checkbox" data-compare="${p.id}" ${compared.includes(p.id)?'checked':''}> Add to comparison</label></article>`).join('');$('#empty').hidden=!!list.length;$('#loadMore').hidden=list.length<=limit;$$('[data-cat]').forEach(b=>b.classList.toggle('active',b.dataset.cat===category));updateCompareBar()}
function reset(){category='All';limit=12;$('#search').value='';$('#makerFilter').value='';$('#useFilter').value='';$('#priced').checked=false;$('#savedFilter').checked=false;$('#sort').value='featured';render()}
function toggleSave(id){saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];write('hm-v2-saved',saved);render()}
function showProduct(id){const p=products.find(p=>p.id===id);if(!p)return;$('#detailBody').innerHTML=`<div class="eyebrow">${esc(p.maker.toUpperCase())} / ${esc(p.category.toUpperCase())}</div>${p.image?`<div class="detail-image">${art(p)}</div>`:''}<h2>${esc(p.name)}</h2><div class="detail-price">${p.price!==null?`${price(p)} <small>${p.currency}</small>`:'Price not published'}</div><p>${esc(p.desc)}</p><div class="detail-specs"><div><small>ACCESS / STATUS</small><strong>${esc(p.status)}</strong></div><div><small>PLATFORM TYPE</small><strong>${esc(p.form||'Humanoid platform')}</strong></div>${Object.entries(p.specs||{}).map(([k,v])=>`<div><small>${esc(k.toUpperCase())}</small><strong>${esc(v)}</strong></div>`).join('')}</div><div class="source-note"><strong>OFFER & CONFIGURATION NOTES</strong><p>${esc(p.note)}</p><p class="source-date">Reviewed ${esc(new Date((p.checked||p.checked_date||"2026-10-24")+"T12:00:00Z").toLocaleDateString("en-US",{year:"numeric",month:"long",day:"numeric",timeZone:"UTC"}))} · Manufacturer-authored information. Capabilities are manufacturer claims, not independent test results. Price and availability can change.</p></div><div class="detail-actions"><a class="button primary" href="${esc(p.source)}" target="_blank" rel="noopener">${p.status==='Preorder'?'View official preorder':p.price!==null?'View official listing':'Visit manufacturer'} ↗</a><button class="button subtle" id="detailSave">${saved.includes(id)?'Remove from saved':'Save hardware'} ♡</button><button class="text-link" id="detailCompare">${compared.includes(id)?'Remove comparison':'Add to comparison'} ＋</button></div><p class="source-date">Source: ${esc(new URL(p.source).hostname)} · Purchase and inquiries take place with the manufacturer. HUMANOID is an independent discovery catalog.</p>`;$('#detailSave').onclick=()=>{toggleSave(id);$('#detailSave').textContent=saved.includes(id)?'Remove from saved ♡':'Save hardware ♡'};$('#detailCompare').onclick=()=>{toggleCompare(id);$('#detailCompare').textContent=compared.includes(id)?'Remove comparison':'Add to comparison ＋'};$('#detail').showModal()}
function toggleCompare(id){if(compared.includes(id))compared=compared.filter(x=>x!==id);else if(compared.length<3)compared.push(id);else toast('Compare up to 3 platforms at a time.');render()}
function updateCompareBar(){$('#compareBar').hidden=!compared.length;$('#compareCount').textContent=compared.length}
function showComparison(){const list=compared.map(id=>products.find(p=>p.id===id));if(!list.length)return;const specs=[...new Set(list.flatMap(p=>Object.keys(p.specs||{})))];const rows=[['Manufacturer',p=>p.maker],['Category',p=>p.category],['Application',p=>p.use],['Platform',p=>p.form||'Not specified'],['Access',p=>p.status],['Published price',p=>p.price===null?'Not published':`${price(p)} ${p.currency}`],...specs.map(k=>[k,p=>p.specs?.[k]||'Not recorded'])];$('#comparisonBody').innerHTML=`<div class="comparison-table"><table><thead><tr><th>PLATFORM</th>${list.map(p=>`<th>${esc(p.name)}</th>`).join('')}</tr></thead><tbody>${rows.map(([k,f])=>`<tr><td>${esc(k)}</td>${list.map(p=>`<td>${esc(f(p))}</td>`).join('')}</tr>`).join('')}<tr><td>Official source</td>${list.map(p=>`<td><a href="${esc(p.source)}" target="_blank" rel="noopener">Manufacturer ↗</a></td>`).join('')}</tr></tbody></table></div><p class="source-date">Specification values refer to the documented configuration and are manufacturer claims. “Not recorded” means this catalog has no verified value, not that the feature is absent. Review each official listing before comparing costs.</p>`;$('#comparison').showModal()}

let timer;function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('#toast').style.display='none',3500)}
$$('[data-cat]').forEach(b=>b.onclick=()=>{category=b.dataset.cat;limit=12;render()});['#search','#makerFilter','#useFilter','#priced','#savedFilter','#sort'].forEach(s=>{$(s).addEventListener(s==='#search'?'input':'change',()=>{limit=12;render()})});$('#clear').onclick=reset;$('#emptyReset').onclick=reset;$('#loadMore').onclick=()=>{limit+=12;render()};$('#saved').onclick=()=>{$('#savedFilter').checked=!$('#savedFilter').checked;limit=12;render();$('#market').scrollIntoView()};
document.addEventListener('click',e=>{const save=e.target.closest('[data-save]');if(save){toggleSave(save.dataset.save);return}const open=e.target.closest('[data-open]');if(open)showProduct(open.dataset.open)});document.addEventListener('change',e=>{if(e.target.matches('[data-compare]'))toggleCompare(e.target.dataset.compare)});$('#compareNow').onclick=showComparison;$('#clearCompare').onclick=()=>{compared=[];render()};$$('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());

const draftKey='hm-local-drafts';function renderDrafts(){const drafts=read(draftKey,[]);$('#drafts').innerHTML=drafts.length?`<p>LOCAL DRAFTS (${drafts.length})</p>${drafts.map(d=>`<p><strong>${esc(d.name)}</strong> · ${esc(d.category)} · $${esc(d.price)}<br><span class="muted">${esc(d.desc)}</span></p>`).join('')}`:''}['#sell','#sell2'].forEach(s=>$(s).onclick=()=>{renderDrafts();$('#listing').showModal()});$('#listingForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),draft={name:f.get('name').trim(),category:f.get('category'),price:Number(f.get('price')),desc:f.get('desc').trim()};if(!draft.name||!draft.desc)return;if(write(draftKey,[draft,...read(draftKey,[])])){renderDrafts();e.target.reset();toast('Draft saved locally. It has not been published.')}};
$('#makerFilter').innerHTML+=[...new Set(products.map(p=>p.maker))].sort().map(m=>`<option value="${esc(m)}">${esc(m)}</option>`).join('');render();
